package com.eventhub.service; import com.eventhub.dto.NotificationResponse; import com.eventhub.entity.*; import com.eventhub.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service @RequiredArgsConstructor public class NotificationService {private final NotificationRepository repo; private final UserRepository users; @Transactional public void send(User user,String title,String message,NotificationType type){repo.save(Notification.builder().user(user).title(title).message(message).type(type).build());} @Transactional(readOnly=true) public Page<NotificationResponse> list(String email,int page,int size){User u=user(email);return repo.findByUserIdOrderByCreatedAtDesc(u.getId(),PageRequest.of(Math.max(page,0),Math.min(Math.max(size,1),100))).map(NotificationResponse::from);} @Transactional(readOnly=true) public long unread(String email){return repo.countByUserIdAndReadFalse(user(email).getId());} @Transactional public void read(String email,Long id){Notification n=repo.findByIdAndUserId(id,user(email).getId()).orElseThrow(()->new IllegalArgumentException("Notification not found"));n.setRead(true);} @Transactional public void readAll(String email){repo.findByUserIdOrderByCreatedAtDesc(user(email).getId(),PageRequest.of(0,1000)).forEach(n->{n.setRead(true);repo.save(n);});} private User user(String e){return users.findByEmailIgnoreCase(e).orElseThrow(()->new IllegalArgumentException("User not found"));}}
